(877, '6-60200', 'Donasi', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya donasi atau sumbangan yang diberikan oleh perusahaan kepada pihak eksternal, seperti organisasi amal atau kegiatan sosial.', '2025-04-23 02:04:45', 6),
(878, '6-60201', 'Hiburan', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya hiburan yang dikeluarkan untuk menjalin hubungan bisnis atau acara perusahaan, seperti makan malam atau pertemuan informal.', '2025-04-23 02:04:45', 6),
(879, '6-60202', 'Bensin - Toll - dan Parkir - Umum', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya transportasi umum yang dikeluarkan untuk keperluan operasional perusahaan, termasuk bahan bakar, tol, dan parkir.', '2025-04-23 02:04:45', 6),
(880, '6-60203', 'Perbaikan dan Perawatan', 'beban', 'Biaya Operasional', 'debit', -11633420.00, 'Biaya perbaikan dan perawatan aset tetap, seperti kendaraan, bangunan, atau peralatan, untuk menjaga kondisinya tetap optimal.', '2025-04-23 02:04:45', 6),
(881, '6-60204', 'Perjalanan (Travelling) - Umum', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya perjalanan umum yang dikeluarkan untuk keperluan operasional perusahaan, seperti kunjungan ke mitra bisnis atau pelanggan.', '2025-04-23 02:04:45', 6),
(882, '6-60205', 'Konsumsi', 'beban', 'Biaya Operasional', 'debit', -1305000.00, 'Biaya konsumsi yang dikeluarkan untuk rapat, acara, atau kegiatan perusahaan, seperti makanan dan minuman.', '2025-04-23 02:04:45', 6),
(883, '6-60206', 'Komunikasi - Umum', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya komunikasi umum, seperti telepon, internet, atau pos, yang digunakan untuk mendukung operasional perusahaan.', '2025-04-23 02:04:45', 6),
(884, '6-60207', 'Iuran & Berlangganan', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Iuran atau biaya berlangganan untuk layanan tertentu, seperti software, majalah, atau jurnal.', '2025-04-23 02:04:45', 6),
(885, '6-60208', 'Asuransi', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Premi asuransi yang dibayarkan untuk melindungi aset atau operasional perusahaan, seperti asuransi kendaraan, bangunan, atau karyawan.', '2025-04-23 02:04:45', 6),
(886, '6-60209', 'Biaya Hukum & Professional', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya jasa hukum atau profesional, seperti konsultan, auditor, atau pengacara, yang digunakan untuk mendukung operasional perusahaan.', '2025-04-23 02:04:45', 6),
(887, '6-60210', 'Beban Tunjangan Karyawan', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Tunjangan tambahan yang diberikan kepada karyawan, seperti tunjangan kesehatan, transportasi, atau makan.', '2025-04-23 02:04:45', 6),
(888, '6-60211', 'Sarana Kantor', 'beban', 'Biaya Operasional', 'debit', -19210000.00, 'Biaya sarana kantor, seperti listrik, air, keamanan, atau kebersihan, yang mendukung operasional sehari-hari.', '2025-04-23 02:04:45', 6),
(889, '6-60212', 'Pelatihan & Pengembangan', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya pelatihan dan pengembangan karyawan untuk meningkatkan keterampilan dan produktivitas mereka.', '2025-04-23 02:04:45', 6),
(890, '6-60213', 'Beban Hutang Buruk', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Kerugian yang timbul dari piutang yang tidak dapat ditagih atau hutang buruk dari pelanggan.', '2025-04-23 02:04:45', 6),
(891, '6-60214', 'Pajak & Lisensi', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Biaya pajak dan lisensi yang harus dibayar oleh perusahaan, seperti pajak daerah atau izin usaha.', '2025-04-23 02:04:45', 6),
(892, '6-60215', 'Denda', 'beban', 'Biaya Operasional', 'debit', 0.00, 'Denda atau sanksi yang dikenakan kepada perusahaan atas pelanggaran tertentu, seperti keterlambatan pembayaran atau pelanggaran aturan.', '2025-04-23 02:04:45', 6),
